/**
 * Cloudflare Access JWT verification inside the Worker, fail closed (SPEC 15).
 *
 * Production: keys from https://<team>.cloudflareaccess.com/cdn-cgi/access/certs (rotated by Cloudflare,
 * never hard-coded), issuer = the team domain, audience = the application AUD tag.
 * Local: the same verifier with a JWKS generated by `npm run dev:keys` and tokens from `npm run dev:token`.
 *
 * A service-token JWT carries `common_name` = the Client ID, an empty `sub` and no `email`, so neither `sub`
 * nor `email` is required; a non-empty `common_name` marks a service principal.
 */
import { createLocalJWKSet, createRemoteJWKSet, type JWTPayload, jwtVerify } from 'jose';
import type { AppEnv } from '../env';
import { type Principal, parseRoleMap, rolesFor } from './roles';

export const ACCESS_HEADER = 'Cf-Access-Jwt-Assertion';

type KeySet = ReturnType<typeof createRemoteJWKSet> | ReturnType<typeof createLocalJWKSet>;
const remoteSets = new Map<string, KeySet>();

function keySet(env: AppEnv): KeySet | null {
  if (env.ACCESS_MODE === 'cloudflare') {
    const team = (env.ACCESS_TEAM_DOMAIN ?? '').replace(/\/+$/, '');
    if (!/^https:\/\/[a-z0-9-]+\.cloudflareaccess\.com$/.test(team)) return null;
    let set = remoteSets.get(team);
    if (!set) {
      set = createRemoteJWKSet(new URL(`${team}/cdn-cgi/access/certs`));
      remoteSets.set(team, set);
    }
    return set;
  }
  if (!env.ACCESS_JWKS_JSON) return null;
  try {
    return createLocalJWKSet(JSON.parse(env.ACCESS_JWKS_JSON));
  } catch {
    return null;
  }
}

function issuer(env: AppEnv): string | null {
  if (env.ACCESS_MODE === 'cloudflare') return (env.ACCESS_TEAM_DOMAIN ?? '').replace(/\/+$/, '') || null;
  return env.ACCESS_ISSUER || null;
}

export type AuthOutcome = { ok: true; principal: Principal } | { ok: false; status: 401 | 403 };

export function principalFrom(payload: JWTPayload): { kind: Principal['kind']; id: string } | null {
  const cn = payload['common_name'];
  if (typeof cn === 'string' && cn.length > 0) return { kind: 'service', id: cn };
  const email = payload['email'];
  if (typeof email === 'string' && email.includes('@')) return { kind: 'human', id: email };
  return null;
}

export async function authenticate(request: Request, env: AppEnv): Promise<AuthOutcome> {
  const token = request.headers.get(ACCESS_HEADER);
  const aud = env.ACCESS_AUD;
  const keys = keySet(env);
  const iss = issuer(env);
  if (!token || !aud || aud === 'unset' || !keys || !iss) return { ok: false, status: 401 };
  let payload: JWTPayload;
  try {
    ({ payload } = await jwtVerify(token, keys, { issuer: iss, audience: aud, algorithms: ['RS256'] }));
  } catch {
    return { ok: false, status: 401 };
  }
  const who = principalFrom(payload);
  if (!who) return { ok: false, status: 401 };
  const roles = rolesFor(parseRoleMap(env.ROLE_MAP_JSON), who.kind, who.id);
  if (roles.length === 0) return { ok: false, status: 403 };
  return { ok: true, principal: { ...who, roles } };
}
